      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.the_document_left_that_question_open_the-v2"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.the_longer_answer_is_that_educational_te-2026-07-12T16:25:19.230926+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-12T16:25:19.230926+00:00",
      "actor": {
        "@id": "agent:DEEPL-API-Free"
      },
      "prov:overwroteTranslationBy": "OLLAMA-mistral-nemo:12b [Profile: Technical/Legal Documentation | Temp: 0.1]",
      "prov:overwriteReason": "qa_score=90: evaluator_flagged",
      "prov:qaEvaluatorNote": "\"「The longer answer is that educational technology spent those years solving the wrong problem.\" -- major"
    },
    {
      "@id": "entity:target-pages_originstorypage.the_longer_answer_is_that_educational_te-v2",
      "@type": "prov:Entity",
      "prov:value": "もう少し詳しく言えば、教育テクノロジーは長年にわたり、間違った問題の解決に取り組んできたのです。EdTechは教室という場そのものを改良し続けてきました――より優れたLMS、より優れた動画、より優れたクイズツールなど。それによって、既存のモデルをより効率的なものにしました。Peripateticwareは、教室の効率化を目指しているわけではありません。少なくとも時折は、教室の代わりに「世界」そのものを活用しようとしているのです。",
      "generated_by": {
        "@id": "activity:translation-pages_originstorypage.the_longer_answer_is_that_educational_te-2026-07-12T16:25:19.230926+00:00"
      },
