    {
      "@id": "activity:translation-pages_originstorypage.the_paper_was_written_at_a_moment_when_3-2026-11-25T18:26:10.345166+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-25T18:26:10.345166+00:00",
