      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.the_longer_answer_is_that_educational_te-v3"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.thats_a_harder_sell_schools_are_riskaver-2026-11-25T18:26:10.345166+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-25T18:26:10.345166+00:00",
