    {
      "@id": "activity:translation-pages_originstorypage.the_longer_answer_is_that_educational_te-2026-11-26T01:53:31.180744+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-26T01:53:31.180744+00:00",
      "actor": {
        "@id": "agent:MICROSOFT-Azure-Cognitive-v3_(unconfigured,_pass-through)_Profile__Technical/Legal_Documentation_|_Temp__0.1"
