      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.peripateticware_doesnt_fully_solve_the_c-v4"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.the_short_answer_is_that_most_of_the_ena-2026-11-26T03:40:48.478087+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-26T03:40:48.478087+00:00",
      "actor": {
        "@id": "agent:MICROSOFT-Azure-Cognitive-v3_(unconfigured,_pass-through)_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:target-pages_originstorypage.the_short_answer_is_that_most_of_the_ena-v5",
      "@type": "prov:Entity",
      "prov:value": "The short answer is that most of the enabling technology wasn\\'t ready in 2007. GPS in every pocket came first (2010–2015). Then high-quality mobile cameras. Then cloud APIs cheap enough for schools. Then local AI models (Ollama, llama.cpp) that can run on a teacher\\'s home server without a $10,000/month inference bill. The 2007 paper was right about the destination; it couldn\\'t have known how long the road would be.",
      "generated_by": {
        "@id": "activity:translation-pages_originstorypage.the_short_answer_is_that_most_of_the_ena-2026-11-26T03:40:48.478087+00:00"
      },
      "used_source": {
