      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.peripateticware_doesnt_fully_solve_the_c-v8"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.the_short_answer_is_that_most_of_the_ena-2026-11-27T01:32:31.111274+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T01:32:31.111274+00:00",
