      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.the_short_answer_is_that_most_of_the_ena-v8"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.the_longer_answer_is_that_educational_te-2026-11-27T01:32:31.111274+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T01:32:31.111274+00:00",
      "actor": {
        "@id": "agent:MICROSOFT-Azure-Cognitive-v3_(unconfigured,_pass-through)_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:target-pages_originstorypage.the_longer_answer_is_that_educational_te-v10",
      "@type": "prov:Entity",
      "prov:value": "The longer answer is that educational technology spent those years solving the wrong problem. EdTech iterated on the classroom — better LMS, better video, better quiz tools. It made the existing model more efficient. Peripateticware doesn\\'t try to make the classroom more efficient. It tries to replace the classroom, at least occasionally, with the world.",
      "generated_by": {
        "@id": "activity:translation-pages_originstorypage.the_longer_answer_is_that_educational_te-2026-11-27T01:32:31.111274+00:00"
      },
      "used_source": {
        "@id": "entity:source-pages_originstorypage.the_longer_answer_is_that_educational_te"
      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.the_longer_answer_is_that_educational_te-v9"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.thats_a_harder_sell_schools_are_riskaver-2026-11-27T01:32:31.111274+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T01:32:31.111274+00:00",
