    {
      "@id": "activity:translation-pages_originstorypage.peripateticware_doesnt_fully_solve_the_c-2026-11-27T02:42:40.767110+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T02:42:40.767110+00:00",
