      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.the_longer_answer_is_that_educational_te-v10"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.thats_a_harder_sell_schools_are_riskaver-2026-11-27T02:42:40.767110+00:00",
