      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.peripateticware_doesnt_fully_solve_the_c-2026-11-27T03:26:19.011623+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T03:26:19.011623+00:00",
      "actor": {
        "@id": "agent:MICROSOFT-Azure-Cognitive-v3_(unconfigured,_pass-through)_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:target-pages_originstorypage.peripateticware_doesnt_fully_solve_the_c-v11",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware doesn\\'t fully solve the chaos — that tension is real and probably permanent. What it does is give teachers enough structure to stay sane (designed activities, learning targets, completion phases, teacher approval workflows) while giving students enough freedom to actually go somewhere (GPS-triggered content, student-proposed activities, self-directed field notes, peer projects).",
      "generated_by": {
        "@id": "activity:translation-pages_originstorypage.peripateticware_doesnt_fully_solve_the_c-2026-11-27T03:26:19.011623+00:00"
