      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.thats_a_harder_sell_schools_are_riskaver-v10"
      }
    },
    {
      "@id": "activity:translation-team_1_bio-2026-11-27T03:26:19.011623+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T03:26:19.011623+00:00",
      "actor": {
        "@id": "agent:MICROSOFT-Azure-Cognitive-v3_(unconfigured,_pass-through)_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:target-team_1_bio-v11",
      "@type": "prov:Entity",
      "prov:value": "Paul spent a decade as a teacher, four years working for edtechs, and has been experimenting with how to break learning out of books and classrooms for two decades. Peripateticware takes advantage of LLM advancements and leverages mobile technologies to allow students to learn from the world with guidance from their teachers wherever they choose to roam.",
      "generated_by": {
        "@id": "activity:translation-team_1_bio-2026-11-27T03:26:19.011623+00:00"
      },
      "used_source": {
        "@id": "entity:source-team_1_bio"
      },
      "derived_from": {
        "@id": "entity:target-team_1_bio-v10"
      }
    },
