      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.if_students_follow_their_curiosity_throu-v11"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.the_document_left_that_question_open_the-2026-11-27T04:03:39.039948+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T04:03:39.039948+00:00",
      "actor": {
        "@id": "agent:MICROSOFT-Azure-Cognitive-v3_(unconfigured,_pass-through)_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:target-pages_originstorypage.the_document_left_that_question_open_the-v14",
      "@type": "prov:Entity",
      "prov:value": "The document left that question open. The school system didn't solve it either. For nearly two decades, \"outdoor learning\" remained either a vague aspiration or a logistical nightmare — teachers with clipboards, activities that produced no artifact, experiences that disappeared the moment students came back inside.",
      "generated_by": {
        "@id": "activity:translation-pages_originstorypage.the_document_left_that_question_open_the-2026-11-27T04:03:39.039948+00:00"
      },
      "used_source": {
