      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.if_students_follow_their_curiosity_throu-v14"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.the_document_left_that_question_open_the-2026-11-27T04:55:53.985528+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T04:55:53.985528+00:00",
      "actor": {
