      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.the_first_part_was_solved_by_smartphones-2026-11-27T04:55:53.985528+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T04:55:53.985528+00:00",
      "actor": {
        "@id": "agent:MICROSOFT-Azure-Cognitive-v3_(unconfigured,_pass-through)_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:target-pages_originstorypage.the_first_part_was_solved_by_smartphones-v15",
      "@type": "prov:Entity",
      "prov:value": "The first part was solved by smartphones. Photo, audio, GPS coordinates, timestamps — a student at a creek bank can capture more evidence in ten minutes than a field trip clipboard could hold in a day. What remained was the second part: structured inquiry that didn't just document experience but deepened it.",
      "generated_by": {
        "@id": "activity:translation-pages_originstorypage.the_first_part_was_solved_by_smartphones-2026-11-27T04:55:53.985528+00:00"
