    {
      "@id": "activity:translation-pages_originstorypage.thats_where_peri_comes_in_peri_is_peripa-2026-11-27T20:13:10.672759+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T20:13:10.672759+00:00",
      "actor": {
        "@id": "agent:MICROSOFT-Azure-Cognitive-v3_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:target-pages_originstorypage.thats_where_peri_comes_in_peri_is_peripa-v16",
      "@type": "prov:Entity",
      "prov:value": "そこで登場するのがペリです。PeriはPeripateticwareのAIガイドで、ソフトウェア同様、アリストテレスの手法にちなんで名付けられています。Periは質問に答えるのではありません。質問を投げかけます。それはアリストテレスがリセウムで使った5段階の問いかけのシーケンス――関わる、観察する、分析する、説明する、応用する――に従い、認知科学がそれを単なる記憶保持ではなく真の理解への道として裏付けています。Periは生徒の観察を受け取り、次に正しい質問を投げかけます。生徒が正解したら、ペリはその含意を検証します。生徒が曖昧に答えたら、ペリは証拠を求めます。",
      "generated_by": {
        "@id": "activity:translation-pages_originstorypage.thats_where_peri_comes_in_peri_is_peripa-2026-11-27T20:13:10.672759+00:00"
      },
      "used_source": {
        "@id": "entity:source-pages_originstorypage.thats_where_peri_comes_in_peri_is_peripa"
      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.thats_where_peri_comes_in_peri_is_peripa-v15"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.the_result_is_an_artifact_a_field_journa-2026-11-27T20:13:10.672759+00:00",
