    {
      "@id": "activity:translation-pages_originstorypage.the_short_answer_is_that_most_of_the_ena-2026-11-27T20:13:10.672759+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T20:13:10.672759+00:00",
      "actor": {
        "@id": "agent:MICROSOFT-Azure-Cognitive-v3_Profile__Technical/Legal_Documentation_|_Temp__0.1"
