    {
      "@id": "entity:target-refundpolicypage.2_title-v15",
      "@type": "prov:Entity",
      "prov:value": "2. サブスクリプションと請求",
      "generated_by": {
        "@id": "activity:translation-refundpolicypage.2_title-2026-11-27T20:13:11.471035+00:00"
