    },
    {
      "@id": "activity:translation-refundpolicypage.2_body-2026-11-27T20:13:11.471035+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T20:13:11.471035+00:00",
      "actor": {
        "@id": "agent:MICROSOFT-Azure-Cognitive-v3_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:target-refundpolicypage.2_body-v15",
      "@type": "prov:Entity",
      "prov:value": "ご購読いただくと、選択したプラン(月額または年次)の支払いがその時点で行われます。サブスクリプションは、キャンセルされるまで各請求期間終了時に自動的に更新されます。当社の支払いおよび請求は、当店のMerchant of Recordである Paddle.com が担当しています。",
      "generated_by": {
        "@id": "activity:translation-refundpolicypage.2_body-2026-11-27T20:13:11.471035+00:00"
      },
      "used_source": {
